local c=bufSet9522[s:sub(bu0u+2,bu0u+2)] or 0
local d=bufSet9522[s:sub(bu0u+3,bu0u+3)] or 0
local n=(a*262144)+(b*4096)+(c*64)+d
refSet898=refSet898.._v1053006(math.floor((n/65536)%256))
if s:sub(bu0u+2,bu0u+2)~="=" then refSet898=refSet898.._v1053006(math.floor((n/256)%256)) end
